effect.shader:
vec4 fxPortOutput;

vec4 fxPortSample(sampler2D image, vec2 uv) {
    vec4 color = texture2D(image, uv);
    if (color.a > 0.0) color.rgb /= color.a;
    else color.rgb = vec3(0.0);
    return color;
}

void fxPortMain() {
    const float northWest = 0.0;
    const float northEast = 0.0;
    const float southWest = 0.0;
    const float southEast = 0.0;
    vec2 uv = clamp(acScreenNorm, 0.0, 1.0);
    vec2 px = vec2(1.0 / max(acScreenSize.x, 1.0),
                   1.0 / max(acScreenSize.y, 1.0));
    vec4 source = fxPortSample(inputImg.texture, uv);
    float center = 1.0 + 0.5 * uControl2;
    float north = 0.5 * uControl3;
    float west = 0.5 * uControl4;
    float east = 0.5 * uControl5;
    float south = 0.5 * uControl6;
    vec4 sum = source * center;
    sum += fxPortSample(inputImg.texture, clamp(uv + vec2(-px.x, px.y), 0.0, 1.0)) * northWest;
    sum += fxPortSample(inputImg.texture, clamp(uv + vec2(0.0, px.y), 0.0, 1.0)) * north;
    sum += fxPortSample(inputImg.texture, clamp(uv + px, 0.0, 1.0)) * northEast;
    sum += fxPortSample(inputImg.texture, clamp(uv - vec2(px.x, 0.0), 0.0, 1.0)) * west;
    sum += fxPortSample(inputImg.texture, clamp(uv + vec2(px.x, 0.0), 0.0, 1.0)) * east;
    sum += fxPortSample(inputImg.texture, clamp(uv - px, 0.0, 1.0)) * southWest;
    sum += fxPortSample(inputImg.texture, clamp(uv - vec2(0.0, px.y), 0.0, 1.0)) * south;
    sum += fxPortSample(inputImg.texture, clamp(uv + vec2(px.x, -px.y), 0.0, 1.0)) * southEast;
    vec4 value = sum * exp2(uControl7) + vec4(0.25 * uControl8);
    vec4 effected = floor(clamp(value, 0.0, 1.0) * 255.0 + 0.00001) / 255.0;
    fxPortOutput = clamp(mix(source, effected, clamp(uControl1, 0.0, 1.0)), 0.0, 1.0);
}

void main() {
    fxPortMain();
    gl_FragColor = vec4(fxPortOutput.rgb * fxPortOutput.a, fxPortOutput.a);
}
